// Additional hand-curated second-term events from original news reporting.
// Discovery timelines were used only to find stories. Every playable card links
// to the newsroom that reported the underlying event.

const sourceName = (url) => {
  const host = new URL(url).hostname.replace(/^www\./, "");
  if (host.includes("apnews.com")) return "Associated Press";
  if (host.includes("reuters.com")) return "Reuters";
  if (host.includes("bbc.")) return "BBC";
  if (host.includes("theguardian.com")) return "The Guardian";
  if (host.includes("npr.org")) return "NPR";
  if (host.includes("nytimes.com")) return "The New York Times";
  if (host.includes("washingtonpost.com")) return "The Washington Post";
  if (host.includes("nbcnews.com")) return "NBC News";
  if (host.includes("cbsnews.com")) return "CBS News";
  if (host.includes("cnn.com")) return "CNN";
  if (host.includes("politico.com")) return "Politico";
  if (host.includes("axios.com")) return "Axios";
  if (host.includes("usatoday.com")) return "USA Today";
  if (host.includes("pbs.org")) return "PBS";
  if (host.includes("time.com")) return "Time";
  return host;
};

const card = (id, date, title, hint, significance, category, url) => ({
  id,
  date,
  title,
  hint,
  significance,
  category,
  trumpleScore: significance,
  sources: [{ name: sourceName(url), url }],
  status: "approved",
});

